def build():
    targets = [
        ("docs/designs/employee-chat.md", "Employee Chat", "Thiết kế V1 · Chưa triển khai", PROTOTYPE),
        ("docs/reviews/cg01-20261014/report.md", "CG01: bằng chứng và phần còn chặn", "Review không inference · 14/10/2026", '<div class="summary-row"><span>VERIFIED · Source + GET</span><span>NOT VERIFIED · Runtime boundaries</span><span class="blocked">BLOCKED · Không có proof hợp lệ</span></div>'),
        ("docs/decisions/0002-employee-chat.md", "ADR-0002 · Employee Chat", "Quyết định thiết kế đề xuất", ""),
    ]
    icon = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%232a5038'/%3E%3Cpath d='M8 9h16v11H15l-5 4v-4H8z' fill='%23eef3e7'/%3E%3C/svg%3E"
    for name, title, kicker, visual in targets:
        path = ROOT / name
        depth = len(path.relative_to(ROOT / 'docs').parents) - 1
        plan = '../' * depth + 'master-plan.html'
        source = path.read_text()
        notice = 'Tài liệu thiết kế và kiểm định. CG01 vẫn chặn; không tạo proof, grant hoặc gọi inference trong đợt này.'
        page = f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · Agent Corporation</title><link rel="icon" href="{icon}"><style>{STYLE}</style></head><body><header><a href="{plan}">Agent Corporation / Tài liệu V1</a></header><main class="wrap"><div class="eyebrow">{html.escape(kicker)}</div><h1>{html.escape(title)}</h1><div class="notice">{notice}</div>{visual}<article class="doc">{prose(source)}</article></main><footer>Nguồn chuẩn: <a href="{path.name}">{path.name}</a> · Bản trực quan không có kết nối runtime.</footer></body></html>'''
        path.with_suffix('.html').write_text(page)
        print(f'Dựng {path.with_suffix(".html").relative_to(ROOT)}')

if __name__ == '__main__':
    build()
